// 策略进化 page acceptance: PANEL_URL=http://127.0.0.1:8008/ node tests/evolve_browser.cjs
// Serves tests/fixtures/evolve-dashboard.json (generated by tools/evolve/run.py) through route interception.
const { chromium, devices } = require('playwright');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const BASE = process.env.PANEL_URL || 'http://127.0.0.1:8008/';
const dash = JSON.parse(fs.readFileSync(path.join(__dirname, 'fixtures', 'evolve-dashboard.json'), 'utf8'));
(async () => {
  const browser = await chromium.launch();
  const context = await browser.newContext({ ...devices['iPhone 13'] });
  let mode = 'ok';
  await context.addInitScript(() => { try { localStorage.setItem('modi-companion-position', JSON.stringify({ side: 'right', bottom: 20, docked: true })); } catch {} });
  await context.route(/okx\.com/, r => r.abort()); await context.routeWebSocket(/okx\.com/, ws => ws.close());
  await context.route('**/paper-data/evolve/dashboard.json*', r => mode === 'ok' ? r.fulfill({ contentType: 'application/json', body: JSON.stringify(dash) }) : r.fulfill({ status: 404, body: '404' }));
  const page = await context.newPage(), errors = [];
  page.on('pageerror', e => errors.push(String(e)));
  await page.goto(BASE + '#/evolve');
  await page.waitForSelector('#evolve-graph svg');
  assert.equal(await page.locator('[data-nav="evolve"]').getAttribute('aria-current'), 'page');
  assert.match(await page.title(), /策略进化/);
  assert.match(await page.locator('#evolve-loop').innerText(), new RegExp(`${dash.generation}[\\s\\S]*观察波动|观察波动[\\s\\S]*${dash.generation}`));
  assert.equal(await page.locator('#evolve-graph .evo-node').count(), dash.nodes.length);
  assert.equal(await page.locator('#evolve-fitness polyline').count(), 2);
  // The champion is selected first; clicking any node shows its genes and backtest.
  assert.match(await page.locator('#evolve-detail').innerText(), new RegExp(`${dash.champion.id}[\\s\\S]*冠军 · 纸面交易中`));
  const child = dash.nodes.find(n => n.parents.length === 2 && n.parents.every(p => dash.nodes.some(x => x.id === p)));
  await page.locator(`#evolve-graph [data-node="${child.id}"]`).dispatchEvent('click');
  await page.waitForFunction(id => document.querySelector('#evolve-detail h3').textContent.includes(id), child.id);
  const detail = await page.locator('#evolve-detail').innerText();
  assert.match(detail, /训练集 70%/); assert.match(detail, /样本外 30%/); assert.match(detail, /基因/);
  assert.ok(await page.locator(`#evolve-graph [data-node="${child.id}"].sel`).count() === 1);
  assert.ok(await page.locator('#evolve-graph .evo-edge.hot').count() >= 2);                     // lineage highlighted
  // Parent buttons in the detail navigate the lineage.
  await page.locator(`#evolve-detail [data-node="${child.parents[0]}"]`).click();
  await page.waitForFunction(id => document.querySelector('#evolve-detail h3').textContent.includes(id), child.parents[0]);
  // Keyboard: focus a node and press Enter.
  const other = dash.nodes.find(n => n.id !== child.parents[0] && n.id !== dash.champion.id);
  await page.locator(`#evolve-graph [data-node="${other.id}"]`).focus(); await page.keyboard.press('Enter');
  await page.waitForFunction(id => document.querySelector('#evolve-detail h3').textContent.includes(id), other.id);
  assert.match(await page.locator('#evolve-paper').innerText(), /纸面权益[\s\S]*当前冠军/);
  assert.match(await page.locator('#evolve-caption').innerText(), /训练集[\s\S]*样本外/);
  for (const width of [320, 390]) {
    await page.setViewportSize({ width, height: 844 });
    assert.ok(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth), `page overflow at ${width}`);
  }
  // Home shows a compact evolution card that links here.
  await page.goto(BASE + '#/'); await page.waitForSelector('#home-evolve:not([hidden])', { timeout: 20000 }).catch(() => {});
  if (await page.locator('#home-sim').isVisible()) assert.match(await page.locator('#home-evolve').innerText(), new RegExp(`第 ${dash.generation} 代`));
  // Before the first run the page explains what will appear.
  mode = 'missing'; const fresh = await context.newPage(); await fresh.goto(BASE + '#/evolve');
  await fresh.waitForSelector('#evolve-error:not([hidden])');
  assert.match(await fresh.locator('#evolve-error').innerText(), /还没有运行过/);
  assert.deepEqual(errors, []);
  await browser.close();
  console.log('策略进化页验收通过：进化循环与代数、适应度曲线、基因池节点与谱系、点击 / 键盘查看基因与训练 vs 样本外回测、父代跳转、纸面交易、首页卡片、320/390 无溢出、首次运行前提示、pageerror=0。');
})().catch(e => { console.error(e); process.exit(1); });
